(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzr-sj-prepa-gyneco-j10-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzr-sj-prepa-gyneco-j10-sf3\",\n \"titre\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 38,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n   \"sha256\": \"c1e8c2d8402d3b954a7c6fc159ceb6b02b83cb88c53adce6ddd9268aa4b95034\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n     \"slug\": \"prepa-gyneco-j10-sf3\",\n     \"pages\": \"\",\n     \"count\": 38,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de l'accouchement de siège, il ne faut pas toucher au fœtus tant que les pointes des omoplates ne sont pas apparues\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lors de l'expulsion en présentation du siège, l'abstention de toute traction intempestive (ne pas toucher au fœtus jusqu'à l'apparition des pointes des omoplates à la vulve) est indispensable pour prévenir le relèvement des bras et la déflexion de la tête dernière au détroit supérieur.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU L3 — Accouchement en présentation du siège.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La cause infectieuse la plus fréquente de stérilité chez la femme est l'endométrite\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La première cause infectieuse d'infertilité féminine est la salpingite (infection génitale haute atteignant les trompes de Fallope, notamment à Chlamydia trachomatis et gonocoque), responsable d'obturation tubaire et d'adhérences pelviennes, et non l'endométrite.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 44 & 45 : Salpingites aiguës et infertilité conjugale.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hystérosalpingographie et l'hystéroscopie sont 2 examens complémentaires qui sont interdits en cas de suspicion de salpingite.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon le cours sur les explorations fonctionnelles en gynécologie (p. 186) et les salpingites aiguës (chap. 44), toute manœuvre endo-utérine et tout examen opacifiant ou endoscopique de la cavité utérine (hystérosalpingographie, hystéroscopie) sont formellement contre-indiqués en cas d'infection génitale haute suspectée ou évolutive en raison du risque de flambée infectieuse et de pelvipéritonite.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 44 & 46 : Contre-indications de l'hystérosalpingographie (p. 186).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'excès de toilette intime est un facteur favorisant des leucorrhées pathologiques.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les toilettes intimes excessives ou irritantes (douches vaginales, antiseptiques répétés) détruisent la flore vaginale physiologique protectrice (bacilles de Döderlein) et déséquilibrent le pH acide du vagin, favorisant le développement des mycoses (Candida albicans) et vaginoses responsables de leucorrhées pathologiques.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 43 : Les infections génitales basses.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le post-partum, le sérum anti-D dans l'iso-immunisation rhésus se fait impérativement dans les 48 heures après l'accouchement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez une accouchée Rhésus négatif non immunisée donnant naissance à un nouveau-né Rhésus positif, l'injection d'immunoglobulines anti-D (sérum anti-D) doit être administrée dans les 72 heures suivant l'accouchement (et non impérativement dans les 48 heures).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 4 : Allo-immunisation dans le système Rhésus au cours de la grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les cloisons vaginales longitudinales gênent l'évolution de la grossesse et l'accouchement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Contrairement aux cloisons vaginales transversales (diaphragmes vaginaux) qui constituent un obstacle prævia à l'expulsion, les cloisons vaginales longitudinales sont souples, n'entravent pas le déroulement de la grossesse et sont généralement refoulées latéralement ou sectionnées sans difficulté lors de l'accouchement par voie basse.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 38 : Les malformations génitales féminines (p. 142).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse, ce sont les gestantes ayant une sérologie de la toxoplasmose positive qui font l'objet d'une surveillance particulière\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ce sont au contraire les gestantes séronégatives (sérologie négative, donc non immunisées) qui font l'objet d'une surveillance sérologique mensuelle obligatoire jusqu'à l'accouchement et de mesures hygiénodiététiques de prévention afin de dépister une séroconversion per-gravidique.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / Soins obstétricaux L2 — Chap. 5 : Sérologie toxoplasmose et grossesse (p. 11).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le dépistage du diabète gestationnel se fait chez les gestantes ayant un antécédent de gros fœtus et de malformation fœtale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le dépistage ciblé du diabète gestationnel (HGPO à 75 g de glucose entre 24 et 28 SA) est indiqué chez les gestantes présentant des facteurs de risque obstétricaux ou personnels, notamment un antécédent de macrosomie fœtale (gros fœtus ≥ 4 000 g), de malformation congénitale, de mort fœtale in utero inexpliquée, d'obésité ou d'antécédents familiaux de diabète.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 9 : Diabète et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la lymphangite du sein, l'allaitement doit être interrompu.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La lymphangite aiguë du sein est une inflammation superficielle sans infection du lait maternel (signe de Budin négatif) ; il ne faut pas interrompre l'allaitement mais au contraire poursuivre les tétées fréquentes pour assurer un bon drainage mammaire et éviter l'évolution vers l'abcès du sein.\\n\\nSource : Cours SONU L3 / Gynéco-Obstétrique L3 — Affections mammaires des suites de couches (p. 101).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les risques de malformations chez l'embryon et le fœtus surviennent uniquement en cas de primo-infection de la rubéole au cours de la grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Bien que le risque malformatif (rubéole congénitale : atteintes oculaires, auditives, cardiaques) soit majeur lors d'une primo-infection maternelle au 1er trimestre, des cas exceptionnels de transmission fœtale et d'atteintes malformatives ont également été décrits lors d'une réinfection rubéoleuse précoce en début de grossesse.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 5 : Rubéole et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant la rubéole au cours de la grossesse est ou sont juste(s) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elle peut se compliquer d'avortements spontanés\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'une de ses mesures prophylactiques est la vaccination des fillettes en âge scolaire immunisées.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les risques surviennent uniquement en cas de primo-infection de la rubéole au cours de la grossesse.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les anticorps M apparaissent en cas de réinfection.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Il faut nécessairement réaliser la sérologie au cours du 1er trimestre de grossesse.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Elle peut se compliquer d'avortements spontanés ; E. Il faut nécessairement réaliser la sérologie au cours du 1er trimestre de grossesse.\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"La rubéole contractée en début de grossesse peut entraîner des avortements spontanés, des malformations congénitales ou une mort fœtale, et le dépistage sérologique fait partie des examens obligatoires du 1er trimestre. La vaccination concerne les jeunes filles non immunisées, et les IgM sont spécifiques d'une primo-infection (absentes lors d'une réinfection).\\n\\nSource : Cours de Gynéco-Obstétrique L3 / Soins obstétricaux L2 — Sérologies prénatales : rubéole (p. 11).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant la présentation de siège est ou sont juste(s) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La prématurité est une étiologie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le repère de la présentation du siège est le coccyx du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"En cas de siège complet le segment inférieur est bien formé et épais\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"À dilatation complète du col mettre en place une perfusion d'ocytocine 5 UI dans 500 ml de sérum glucosé isotonique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le foyer maximal des bruits du cœur fœtal est entendu au-dessous et en dehors de l'ombilic.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. La prématurité est une étiologie ; B. Le repère de la présentation du siège est le coccyx du fœtus ; D. À dilatation complète du col mettre en place une perfusion d'ocytocine 5 UI dans 500 ml de sérum glucosé isotonique\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La prématurité (absence de culbute physiologique du 7e mois) est une étiologie classique du siège, son repère anatomique est le sacrum/coccyx du fœtus, et à dilatation complète une perfusion d'ocytocine (5 UI dans 500 ml de SGI) est recommandée pour soutenir les contractions lors de l'expulsion. Le foyer des BDCF s'entend au-dessus de l'ombilic et le segment inférieur est mal amplié dans le siège complet.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 22 & 23 : Présentation et accouchement du siège.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les indications de l'amnioscopie sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La prééclampsie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le diagnostic de fissuration des membranes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les leucorrhées pathologiques\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le dépassement de terme\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les Métrorragies\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. La prééclampsie ; D. Le dépassement de terme\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"L'amnioscopie (observation endoscopique transcervicale de la couleur et de l'abondance du liquide amniotique à travers les membranes intactes en fin de grossesse) est indiquée dans la surveillance des grossesses à haut risque fœtal telles que le dépassement de terme et la pré-éclampsie (ou le diabète/RCIU) pour dépister une souffrance fœtale (liquide teinté ou méconial). Les métrorragies, la rupture des membranes et les infections vaginales en sont des contre-indications.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 46 : Les explorations fonctionnelles en gynécologie-obstétrique.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les complications des hépatites virales sur la grossesse et sur l'accouchement sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le coma\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'hémorragie de la délivrance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les hépatites virales congénitales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les troubles respiratoires\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'accouchement prématuré\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. L'hémorragie de la délivrance ; C. Les hépatites virales congénitales ; E. L'accouchement prématuré\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Au cours de la grossesse, les hépatites virales exposent à un risque accru d'accouchement prématuré (lié à la fièvre et à l'atteinte hépatique), d'hémorragie de la délivrance (due à l'insuffisance hépatocellulaire avec baisse des facteurs de coagulation et du TP) et de transmission mère-enfant (hépatites virales congénitales/néonatales).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 6 : Infections virales (hépatites) et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ou les causes fréquente(s) d'anémie au cours de la grossesse est ou sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La grossesse molaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La menace d'accouchement prématuré\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le placenta prævia\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le paludisme\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La toxoplasmose\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Le paludisme\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"En zone d'endémie tropicale, à côté de la carence martiale et folique, le paludisme (par hémolyse parasitaire des hématies et hypersplénisme) constitue l'une des causes les plus fréquentes d'anémie gravidique sévère.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU L3 — Anémie et paludisme au cours de la grossesse (p. 2 & 27).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles de ces assertions concernant les salpingites aiguës est ou sont juste(s)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elles se manifestent par une fièvre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les manœuvres endo-utérines en sont un facteur de risque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elles surviennent en majorité chez les patientes de plus de 25 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Elles se manifestent par des Leucorrhées louches purulentes\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le traitement repose sur une monoantibiothérapie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Elles se manifestent par une fièvre ; B. Les manœuvres endo-utérines en sont un facteur de risque ; D. Elles se manifestent par des Leucorrhées louches purulentes\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Les salpingites aiguës associent une douleur pelvienne, de la fièvre (38-39 °C) et des leucorrhées louches ou purulentes ; elles sont favorisées par les IST (touchant surtout les femmes jeunes de moins de 25 ans) et les manœuvres endo-utérines (pose de DIU, curetage, HSG). Leur traitement repose sur une poly-antibiothérapie à large spectre et non une monothérapie.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 44 : Les infections génitales hautes (salpingites aiguës).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les complications des traumatismes au cours de la grossesse sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le placenta prævia\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'hématome rétroplacentaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La rupture prématurée des membranes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La rupture utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'accouchement prématuré\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. L'hématome rétroplacentaire ; C. La rupture prématurée des membranes ; D. La rupture utérine ; E. L'accouchement prématuré\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Un traumatisme abdominal ou général (accident de la voie publique, chute, coups) chez la femme enceinte peut déclencher un décollement prématuré du placenta (hématome rétroplacentaire), une rupture utérine (notamment sur utérus gravide volumineux ou cicatriciel), une rupture prématurée des membranes et un accouchement prématuré. Le placenta prævia est une anomalie d'implantation et non une complication traumatique.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Traumatismes et grossesse / Complications obstétricales.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant la consultation post-natale est ou sont juste(s)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'examen au spéculum et le toucher vaginal ne sont pas systématiques pendant la 2e CPON\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dans la nouvelle conception de consultation post natale, l'accouchée normale, doit bénéficier de trois CPON dans les 6 semaines après l'accouchement.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La 3ème visite post-natale de l'accouchée se fait pendant la 6ème semaine après l'accouchement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il faut examiner la mère et son enfant\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Il faut conseiller la rééducation abdominale qui doit commencer avant la rééducation périnéale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Dans la nouvelle conception de consultation post natale, l'accouchée normale, doit bénéficier de trois CPON dans les 6 semaines après l'accouchement. ; C. La 3ème visite post-natale de l'accouchée se fait pendant la 6ème semaine après l'accouchement ; D. Il faut examiner la mère et son enfant\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Selon le nouveau protocole national de suivi post-natal (chap. 39, p. 149-154), l'accouchée normale bénéficie de trois CPoN (à la 1re semaine, à la 3e semaine et à la 6ème semaine) portant systématiquement sur l'examen clinique de la mère et du nouveau-né (avec examen au spéculum et TV lors de la 2e/3e CPoN). La rééducation périnéale doit toujours précéder la rééducation abdominale.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 39 : Les consultations post-natales (CPoN) (p. 149-154).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La cystite aiguë se manifeste par les signes suivants :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La douleur lombaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La brûlure urétrale basse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La pollakiurie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La fièvre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les mictions impérieuses\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La brûlure urétrale basse ; C. La pollakiurie ; E. Les mictions impérieuses\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Conformément au cours sur les infections urinaires et grossesse (p. 113), la cystite aiguë est une infection urinaire basse apyrétique associant pollakiurie, brûlures urétrales basses (mictionnelles) et mictions impérieuses, sans fièvre ni douleur lombaire (qui caractérisent la pyélonéphrite aiguë).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 27 : Les infections urinaires et grossesse (p. 113).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le ou les examen(s) complémentaire(s) ci-dessous ne fait ou font pas partie du bilan de base du couple infertile :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le spermogramme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le Test post coïtal de Hühner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le dosage plasmatique de l'œstradiol\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La cœlioscopie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'hystérosalpingographie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. La cœlioscopie\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le bilan d'exploration de première intention (bilan de base) d'un couple infertile comprend le spermogramme/spermocytogramme chez l'homme, le test post-coïtal de Hühner, les dosages hormonaux plasmatiques (FSH, LH, œstradiol, AMH, progestérone) et l'hystérosalpingographie chez la femme ; la cœlioscopie diagnostique est un examen invasif de seconde intention réservé aux anomalies tubaires ou pelviennes suspectées.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 45 & 46 : Infertilité conjugale et explorations fonctionnelles (p. 186).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les conséquences de l'allo-immunisation sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le décès fœtal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La macrosomie fœtale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'hypertrophie du rein\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'hyperbilirubinémie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'anémie fœtale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le décès fœtal ; D. L'hyperbilirubinémie ; E. L'anémie fœtale\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Dans l'allo-immunisation fœto-maternelle Rhésus, les anticorps maternels anti-D traversent le placenta et détruisent les hématies fœtales (maladie hémolytique), entraînant une anémie fœtale (pouvant évoluer vers l'anasarque fœto-placentaire et le décès fœtal in utero) ainsi qu'une hyperbilirubinémie responsable d'un ictère néonatal précoce et sévère (ictère nucléaire).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 4 : Allo-immunisation dans le système Rhésus au cours de la grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après avoir réalisé la GATPA, certains gestes s'imposent. À savoir :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faire immédiatement une révision utérine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Examiner soigneusement le nouveau-né\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Procéder à la réfection des déchirures cervicales, vaginales ou de l'épisiotomie.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Assurer une surveillance stricte dans le post-partum du globe utérin\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Examiner le placenta et les membranes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Procéder à la réfection des déchirures cervicales, vaginales ou de l'épisiotomie. ; D. Assurer une surveillance stricte dans le post-partum du globe utérin ; E. Examiner le placenta et les membranes\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Immédiatement après l'expulsion du placenta obtenue par la GATPA, la sage-femme doit examiner minutieusement le placenta et les membranes pour vérifier leur intégrité, vérifier la filière génitale et procéder à la réfection des déchirures ou de l'épisiotomie, et assurer une surveillance stricte du globe utérin de sécurité (ainsi que des constantes et saignements). La révision utérine n'est jamais systématique si le placenta est complet.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / Soins obstétricaux L2 — Chap. 13 & 15 : La GATPA et la délivrance (p. 50, 73-78).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ménopause peut s'accompagner des signes suivants :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Amaigrissement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dyspareunie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Bouffées de chaleur\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Métrorragies\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Atrophie vulvaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Dyspareunie ; C. Bouffées de chaleur ; E. Atrophie vulvaire\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"La carence œstrogénique de la ménopause confirmée entraîne des troubles climatériques vasomoteurs (bouffées de chaleur, sueurs nocturnes) et des signes d'atrophie urogénitale (sécheresse vaginale, atrophie vulvaire et dyspareunie). Toute métrorragie survenant après la ménopause est pathologique et doit faire rechercher un cancer de l'endomètre.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 40 : La ménopause.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ou les complications du paludisme sur la grossesse est ou sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le neuropaludisme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'accouchement prématuré\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le mort-né\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'anémie sévère\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'hypotrophie fœtale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. L'accouchement prématuré ; C. Le mort-né ; E. L'hypotrophie fœtale\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le cours distingue les complications du paludisme sur la grossesse (avortement spontané, accouchement prématuré, mort-né, naissance d'un enfant de petit poids / hypotrophie fœtale, paludisme congénital) des complications maternelles de la grossesse sur le paludisme (accès graves dont neuropaludisme, anémie grave et décès maternel).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 1 : Paludisme et grossesse (III-1, p. 2).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant la COVID-19 au cours de la grossesse est ou sont juste(s) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il faut séparer le couple mère-enfant lorsque le pronostic vital de la mère et de l'enfant sont bien engagés\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il y a un risque de malformation fœtale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'allaitement est contre-indiqué\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il y a un risque élevé de transmission verticale prénatale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Elle peut se compliquer de prééclampsie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Il faut séparer le couple mère-enfant lorsque le pronostic vital de la mère et de l'enfant sont bien engagés ; E. Elle peut se compliquer de prééclampsie\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Au cours de la grossesse, la COVID-19 peut se compliquer de syndromes hypertensifs/prééclampsie, et la séparation mère-nouveau-né n'est envisagée que lorsque l'état clinique grave de la mère ou de l'enfant l'impose (hospitalisation en réanimation). L'allaitement maternel n'est pas contre-indiqué (sous mesures barrières), et il n'existe ni tératogénicité ni transmission verticale prénatale élevée.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 6 : Infection au COVID-19 et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La mort in utero peut se compliquer de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les troubles de la coagulation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La chorio-amniotite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les troubles psychologiques\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La présentation dystocique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La rupture utérine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les troubles de la coagulation ; B. La chorio-amniotite ; C. Les troubles psychologiques\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"La mort fœtale in utero (MFIU) expose la mère à trois ordres de complications majeures : des troubles de la coagulation (CIVD / fibrinolyse par libération de thromboplastines ovulaires en cas de rétention prolongée), des complications infectieuses graves (chorio-amniotite, endométrite, septicémie surtout si les membranes sont rompues) et un important retentissement psychologique (deuil périnatal, dépression).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 29 : La mort fœtale (mort in utero).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les composantes principales des soins après avortement sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le renforcement des forces de la communauté par le biais de la sensibilisation et la mobilisation communautaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'évaluation rapide du choc et le diagnostic continu des signes de complication\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le counseling et la prestation de planification familiale, l'évaluation et le traitement des IST et le counseling et/ou référence pour les tests et les services volontaires de VIH\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La préparation au traitement et soins tels que nécessaires\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le traitement d'urgence pour les complications de l'avortement spontané et de l'avortement provoqué\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le renforcement des forces de la communauté par le biais de la sensibilisation et la mobilisation communautaires ; C. Le counseling et la prestation de planification familiale, l'évaluation et le traitement des IST et le counseling et/ou référence pour les tests et les services volontaires de VIH ; E. Le traitement d'urgence pour les complications de l'avortement spontané et de l'avortement provoqué\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Selon le modèle des Soins Après Avortement (SAA) enseigné en L3 (chap. 42, p. 170), les composantes principales regroupent : le traitement d'urgence de l'avortement incomplet et de ses complications, le counseling et les services de planification familiale intégrés aux soins IST/VIH, ainsi que le partenariat et la mobilisation communautaire. Les propositions B et D sont des étapes opératoires de la prise en charge clinique.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 42 : Les soins après avortement (SAA) (p. 170).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant le traitement préventif du paludisme au cours de la grossesse :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Si la femme enceinte est allergique à la Sulfadoxine-Pyriméthamine, la prévention du paludisme se fera par l'artéméther\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'usage de moustiquaire imprégnée d'insecticide à longue durée d'action et rapide MILDA doit débuter après 16 semaines de grossesse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Chez la femme enceinte séropositive au VIH sous prophylaxie au Cotrimoxazole il n'est pas recommandé d'administrer, encore, la Sulfadoxine-Pyriméthamine en traitement préventif intermittent\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La chimioprophylaxie est obligatoire chez toutes les femmes\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'administration de la Sulfadoxine-Pyriméthamine est conseillée au premier trimestre de la grossesse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Chez la femme enceinte séropositive au VIH sous prophylaxie au Cotrimoxazole il n'est pas recommandé d'administrer, encore, la Sulfadoxine-Pyriméthamine en traitement préventif intermittent\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Chez la femme enceinte infectée par le VIH recevant déjà une prophylaxie quotidienne au cotrimoxazole (sulfaméthoxazole-triméthoprime), l'administration concomitante de Sulfadoxine-Pyriméthamine (SP) est formellement contre-indiquée en raison du risque cumulatif de toxicité sévère aux sulfamides (syndrome de Stevens-Johnson, aplasie médullaire). La MILDA s'utilise dès le 1er trimestre, et la SP est interdite au 1er trimestre.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU L3 — Paludisme et VIH au cours de la grossesse (p. 2 & 9).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le ou les facteur(s) favorisant l'endométrite est ou sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les touchers vaginaux aseptiques\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La Rupture Prématurée des Membranes supérieure à 12 heures\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le transfert précoce des parturientes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'hémorragie de la délivrance\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le travail d'accouchement prolongé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La Rupture Prématurée des Membranes supérieure à 12 heures ; D. L'hémorragie de la délivrance ; E. Le travail d'accouchement prolongé\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"L'endométrite puerpérale est favorisée par l'ouverture prolongée de l'œuf (RPM > 12 heures), le travail prolongé et l'hémorragie de la délivrance (qui affaiblit l'organisme et implique souvent une révision utérine), tandis que des touchers vaginaux aseptiques et un transfert précoce préviennent l'infection.\\n\\nSource : Cours SONU L3 / Gynéco-Obstétrique L3 — Suites de couches pathologiques : endométrite (p. 98).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les contre-indications de la ventouse obstétricale sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La prématurité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"la cardiopathie maternelle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les présentations céphaliques\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"la Malformation fœtale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La disproportion céphalo-pelvienne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. La prématurité ; D. la Malformation fœtale ; E. La disproportion céphalo-pelvienne\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La pose de la ventouse obstétricale est contre-indiquée en cas de prématurité (< 34-36 SA, fragilité vasculaire cérébrale et risque d'hémorragie intraventriculaire), de malformation fœtale céphalique ou d'anomalie de l'hémostase fœtale, et de disproportion céphalo-pelvienne (présentation non engagée). La cardiopathie maternelle est au contraire une indication d'extraction instrumentale pour abréger les efforts expulsifs.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 21 : Les extractions instrumentales (ventouse obstétricale, p. 82).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de malformations utérines, la grossesse et l'accouchement peuvent se compliquer de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La rétention placentaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La présentation du siège\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'endométrite du post-partum\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'accouchement prématuré\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'hématome rétroplacentaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. La rétention placentaire ; B. La présentation du siège ; C. L'endométrite du post-partum ; D. L'accouchement prématuré\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Les malformations utérines congénitales (utérus cloisonné, bicorne, unicorne) réduisent et déforment la cavité utérine, exposant aux avortements à répétition, à l'accouchement prématuré, aux présentations dystociques dont la présentation du siège, ainsi qu'aux anomalies de la délivrance avec rétention placentaire (favorisant secondairement l'endométrite du post-partum).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 38 : Les malformations génitales féminines (p. 142).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels sont les facteurs qui favorisent l'anémie ferriprive au cours de la grossesse :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les infections urinaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les grossesses monofœtales\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La multigestité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les grossesses rapprochées\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les vomissements\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les infections urinaires ; C. La multigestité ; D. Les grossesses rapprochées ; E. Les vomissements\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"L'anémie ferriprive gravidique est favorisée par l'épuisement des réserves maternelles en fer lié à la multigestité et aux grossesses rapprochées, par la réduction des apports due aux vomissements gravidiques, ainsi que par les infections chroniques ou récidivantes telles que les infections urinaires et le paludisme.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU L3 — Anémie chez la femme enceinte (p. 2 & 27).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant les hématomes vulvovaginaux est ou sont juste(s) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ils sont secondaires à un accouchement atraumatique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'infection est une complication\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La multiparité peut être une cause\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ils se manifestent par une douleur\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Ils se manifestent par une sensation de ténesme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. L'infection est une complication ; D. Ils se manifestent par une douleur ; E. Ils se manifestent par une sensation de ténesme\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Les hématomes péri-génitaux (thrombus vulvo-vaginaux) résultent de la rupture vasculaire sousmuqueuse lors d'un accouchement traumatique ou instrumental (souvent chez la primipare) ; ils se révèlent dans les heures suivant l'accouchement par une douleur périnéale intense et croissante associée à une sensation de pesanteur rectale ou de ténesme, et peuvent se compliquer d'hémorragie grave et d'infection (abcédation).\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 20 : Les hématomes péri-génitaux (thrombus génitaux).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE (1ère partie — Q34 à Q35) : Vous recevez ce jour à la maternité de Nimbo, Mme XY, 19 ans G4P1 avec 1 enfant vivant bien portant, 2 antécédents d'avortements provoqués, 1 antécédent d'avortement spontané. Elle a un antécédent de myomectomie, de mutilation génitale féminine. Elle est diabétique et hypertendue chronique. Elle consulte ce jour pour une fièvre à 38°4C évoluant depuis 4 jours sur une grossesse de 31 semaines d'aménorrhée.\",\n       \"text\": \"Citer 3 pathologies fréquentes que vous pouvez évoquer devant cette fièvre chez Mme XY\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Kyste ovarien en torsion\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fièvre typhoïde\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pyélonéphrite aiguë\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cystite aiguë\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Paludisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Fièvre typhoïde ; C. Pyélonéphrite aiguë ; E. Paludisme\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Devant une fièvre élevée (38,4 °C) chez une femme enceinte en zone tropicale, les trois étiologies infectieuses fréquentes à évoquer en priorité sont le paludisme, la pyélonéphrite aiguë (favorisée par la grossesse et le diabète, contrairement à la cystite qui est apyrétique) et la fièvre typhoïde.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU L3 — Chap. 28 : CAT devant une fièvre pendant la grossesse (p. 87).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE (1ère partie — Q34 à Q35) : Vous recevez ce jour à la maternité de Nimbo, Mme XY, 19 ans G4P1 avec 1 enfant vivant bien portant, 2 antécédents d'avortements provoqués, 1 antécédent d'avortement spontané. Elle a un antécédent de myomectomie, de mutilation génitale féminine. Elle est diabétique et hypertendue chronique. Elle consulte ce jour pour une fièvre à 38°4C évoluant depuis 4 jours sur une grossesse de 31 semaines d'aménorrhée.\",\n       \"text\": \"Quels sont les examens paracliniques de première intention que vous pouvez demander devant cette fièvre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Échographie obstétricale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sérodiagnostic de Widal et Félix\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Examen cytobactériologique des urines\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Goutte épaisse\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Hémogramme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Examen cytobactériologique des urines ; D. Goutte épaisse ; E. Hémogramme\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Le bilan paraclinique de première intention devant une fièvre au cours de la grossesse comprend la goutte épaisse (et frottis sanguin / TDR pour le paludisme), l'examen cytobactériologique des urines (ECBU) (pour l'infection urinaire haute) et l'hémogramme (NFS) (pour évaluer le taux d'hémoglobine et les leucocytes).\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU L3 — CAT devant une fièvre en cas de grossesse (p. 87).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE (1ère partie — Q34 à Q35) : Vous recevez ce jour à la maternité de Nimbo, Mme XY, 19 ans G4P1 avec 1 enfant vivant bien portant, 2 antécédents d'avortements provoqués, 1 antécédent d'avortement spontané. Elle a un antécédent de myomectomie, de mutilation génitale féminine. Elle est diabétique et hypertendue chronique. Elle consulte ce jour pour une fièvre à 38°4C évoluant depuis 4 jours sur une grossesse de 31 semaines d'aménorrhée.\\n\\nCAS CLINIQUE (2ème partie — Q36 à Q38) : À l'interrogatoire, Mme XY se plaint également de céphalées, nausées, myalgies, frisson intense avec sensation de froid, peau brûlante mais sèche avec sueur abondante avec une alternance de mieux-être et de reprise des signes toutes les 48 heures. L'examen physique de Mme XY est sans particularités.\",\n       \"text\": \"Quelle est l'étiologie la plus probable de cette fièvre devant ces signes fonctionnels\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fibrome utérin en nécrobiose\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fièvre typhoïde\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pyélonéphrite aiguë\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cystite aiguë\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Paludisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. Paludisme\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"L'évolution par accès fébriles intermittents avec la triade classique « frissons – chaleur – sueurs » se répétant toutes les 48 heures (fièvre tierce), accompagnée d'un syndrome algique (céphalées, myalgies) et digestif (nausées) sans signe de gravité, signe un accès palustre simple à Plasmodium falciparum.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 1 : Paludisme et grossesse (p. 2).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE (1ère partie — Q34 à Q35) : Vous recevez ce jour à la maternité de Nimbo, Mme XY, 19 ans G4P1 avec 1 enfant vivant bien portant, 2 antécédents d'avortements provoqués, 1 antécédent d'avortement spontané. Elle a un antécédent de myomectomie, de mutilation génitale féminine. Elle est diabétique et hypertendue chronique. Elle consulte ce jour pour une fièvre à 38°4C évoluant depuis 4 jours sur une grossesse de 31 semaines d'aménorrhée.\\n\\nCAS CLINIQUE (2ème partie — Q36 à Q38) : À l'interrogatoire, Mme XY se plaint également de céphalées, nausées, myalgies, frisson intense avec sensation de froid, peau brûlante mais sèche avec sueur abondante avec une alternance de mieux-être et de reprise des signes toutes les 48 heures. L'examen physique de Mme XY est sans particularités.\",\n       \"text\": \"Quelles sont les complications que vous redoutez chez Mme XY aujourd'hui\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Avortement spontané\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Souffrance fœtale aiguë\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pyonéphrose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Accouchement prématuré\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Neuropaludisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Souffrance fœtale aiguë ; D. Accouchement prématuré ; E. Neuropaludisme\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"À 31 semaines d'aménorrhée (3e trimestre, au-delà du seuil de 28 SA définissant l'avortement), la fièvre et l'infection palustre font redouter l'accouchement prématuré (par déclenchement de contractions utérines fébriles), la souffrance fœtale aiguë (par hypoxie et hyperthermie) ainsi que l'évolution maternelle vers le paludisme grave (neuropaludisme).\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU L3 — Complications du paludisme au 3e trimestre de grossesse (p. 2 & 87).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j10-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE (1ère partie — Q34 à Q35) : Vous recevez ce jour à la maternité de Nimbo, Mme XY, 19 ans G4P1 avec 1 enfant vivant bien portant, 2 antécédents d'avortements provoqués, 1 antécédent d'avortement spontané. Elle a un antécédent de myomectomie, de mutilation génitale féminine. Elle est diabétique et hypertendue chronique. Elle consulte ce jour pour une fièvre à 38°4C évoluant depuis 4 jours sur une grossesse de 31 semaines d'aménorrhée.\\n\\nCAS CLINIQUE (2ème partie — Q36 à Q38) : À l'interrogatoire, Mme XY se plaint également de céphalées, nausées, myalgies, frisson intense avec sensation de froid, peau brûlante mais sèche avec sueur abondante avec une alternance de mieux-être et de reprise des signes toutes les 48 heures. L'examen physique de Mme XY est sans particularités.\",\n       \"text\": \"Quelle est votre conduite à tenir chez Mme XY\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Administration de quinine par voie orale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Administration de Paracétamol\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Antibiothérapie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Administration d'artésunate injectable\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Tocolyse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Administration de Paracétamol ; D. Administration d'artésunate injectable\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Face à un paludisme évoluant depuis 4 jours chez une gestante à haut risque (31 SA, diabétique et hypertendue chronique), la prise en charge associe le traitement antipaludique curatif de référence par artésunate injectable (suivi du relais oral par CTA) et un antipyrétique par paracétamol (1 g toutes les 6-8 h) pour faire chuter rapidement la fièvre et prévenir les contractions utérines et la souffrance fœtale.\\n\\nSource : Cours de Gynéco-Obstétrique L3 / SONU L3 — Traitement curatif du paludisme chez la femme enceinte (p. 2 & 87). CORRIGÉ EXPLIQUÉ — PRÉPA DE INFAS\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J10 (SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
